def is_prime(n):
    """Check if a number is prime."""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

n = int(input())
a = list(map(int, input().split()))

# Count occurrences of 1 and 2
count_1 = a.count(1)
count_2 = a.count(2)

# Strategy: start with 2 if we have any, then alternate
result = []

# Start with 2 if available
if count_2 > 0:
    result.append(2)
    count_2 -= 1

# Alternate between 1 and 2
while count_1 > 0 or count_2 > 0:
    if count_1 > 0:
        result.append(1)
        count_1 -= 1
    if count_2 > 0:
        result.append(2)
        count_2 -= 1

print(' '.join(map(str, result)))
