{"code": "
import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    strengths = [int(next(it)) for _ in range(n)]
    t = int(next(it))
    queries = []

    for _ in range(t):
        l = int(next(it)) - 1  # 0-indexed
        r = int(next(it)) - 1
        queries.append((l, r))

    # Precompute prefix GCD
    prefix_gcd = [0] * (n + 1)
    for i in range(n):
        prefix_gcd[i + 1] = prefix_gcd[i] if i == 0 else gcd(prefix_gcd[i], strengths[i])

    # For each query, compute segment GCD
    results = []
    for l, r in queries:
        # Compute GCD of segment [l, r]
        segment_gcd = prefix_gcd[r + 1] if l == 0 else gcd(prefix_gcd[r + 1], prefix_gcd[l])

        # Count occurrences of segment_gcd in [l, r]
        count = 0
        for i in range(l, r + 1):
            if strengths[i] == segment_gcd:
                count += 1

        # Check if there are ants with other values
        has_other = False
        for i in range(l, r + 1):
            if strengths[i] != segment_gcd:
                has_other = True
                break

        # If there's exactly one ant with the segment GCD and there are ants with other values
        if count == 1 and has_other:
            results.append(str((r - l + 1) - 1))
        else:
            results.append(str((r - l + 1)))

    sys.stdout.write("\n".join(results))

# Python 3.9+ has math.gcd, but we need to handle Python 3.8 and below
import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

if __name__ == "__main__":
    main()
"}

