n = int(input())
edges = []

# Read all edges
for _ in range(n - 1):
    a, b = map(int, input().split())
    edges.append((a, b))

# Union-Find implementation
class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size + 1))  # 1-indexed
        self.rank = [0] * (size + 1)

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])  # Path compression
        return self.parent[x]

    def union(self, x, y):
        x_root = self.find(x)
        y_root = self.find(y)

        if x_root == y_root:
            return False  # Already in the same set

        # Union by rank
        if self.rank[x_root] < self.rank[y_root]:
            self.parent[x_root] = y_root
        else:
            self.parent[y_root] = x_root
            if self.rank[x_root] == self.rank[y_root]:
                self.rank[x_root] += 1
        return True

# Build the union-find structure
uf = UnionFind(n)
for a, b in edges:
    uf.union(a, b)

# Find all connected components
components = set()
for i in range(1, n + 1):
    components.add(uf.find(i))

num_components = len(components)
t = num_components - 1
print(t)

# Find any two vertices from different components
c1 = None
c2 = None
for i in range(1, n + 1):
    root = uf.find(i)
    if c1 is None:
        c1 = root
        # Find a vertex in a different component
        for j in range(i + 1, n + 1):
            if uf.find(j) != root:
                c2 = uf.find(j)
                break
    elif c2 is None:
        break

# Find any two vertices in each component
# For component c1
v1 = None
for i in range(1, n + 1):
    if uf.find(i) == c1:
        v1 = i
        break

# For component c2
v2 = None
for i in range(1, n + 1):
    if uf.find(i) == c2:
        v2 = i
        break

# Output the plan
# Close a road from component c1 and build a road connecting c1 and c2
# We can close any road in component c1
for a, b in edges:
    if uf.find(a) == c1 and uf.find(b) == c1:
        print(f"{a} {b} {v1} {v2}")
        break
"}

