import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, m, k = map(int, data)

    if m < k:
        # No log can be split
        if n % 2 == 1:
            print("Timur")
        else:
            print("Marsel")
    else:
        # Check if m is a multiple of k and m/k is odd
        if m % k == 0:
            t = m // k
            if t % 2 == 1:
                g = 1
            else:
                g = 0
        else:
            g = 0

        # Total Grundy number
        if n % 2 == 1:
            total = g
        else:
            total = 0

        if total != 0:
            print("Timur")
        else:
            print("Marsel")

if __name__ == "__main__":
    solve()
