def solve():
    T = int(input())
    for _ in range(T):
        t = input().strip()

        # Count frequencies of each letter
        freq = {}
        for ch in t:
            freq[ch] = freq.get(ch, 0) + 1

        # Sort letters by frequency in decreasing order
        sorted_letters = sorted(freq.keys(), key=lambda x: freq[x], reverse=True)

        # The order of removals should be the reverse of the sorted order
        order = sorted_letters[::-1]

        # The original s should be the one with all letters
        original_s = ''.join(sorted_letters)

        # Output the result
        if len(order) == len(sorted_letters):
            print(original_s, ''.join(order))
        else:
            print(-1)

solve()
