import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    operations = []

    # Try to flip from left to right
    for i in range(n):
        if a[i] == 1:
            # Need to flip position i
            if i == n - 1:
                # Can't flip rightmost position
                print("NO")
                return

            # Choose triplet that includes i
            if i == 0:
                # i is leftmost, flip (0, 1, 2)
                triplet = (0, 1, 2)
            elif i == n - 2:
                # i is second to last, flip (i-1, i, i+1)
                triplet = (i-1, i, i+1)
            else:
                # i is middle, flip (i-1, i, i+1)
                triplet = (i-1, i, i+1)

            # Flip the triplet
            for j in range(3):
                a[triplet[j]] ^= 1

            # Record operation
            operations.append((triplet[0]+1, triplet[1]+1, triplet[2]+1))

    # Check if all zeros
    if all(x == 0 for x in a):
        print("YES")
        print(len(operations))
        for op in operations:
            print(op[0], op[1], op[2])
    else:
        print("NO")

if __name__ == "__main__":
