def solve():
    MOD = 1000000007
    d, n = map(int, input().split())
    a = list(map(int, input().split()))

    # Build adjacency list
    from collections import defaultdict
    adj = defaultdict(list)
    for _ in range(n - 1):
        u, v = map(int, input().split())
        adj[u - 1].append(v - 1)
        adj[v - 1].append(u - 1)

    # DP: dp[u][k] = number of valid sets in subtree rooted at u with sum exactly k
    # We'll use a list of dictionaries for DP
    dp = [{} for _ in range(n)]

    def dfs(u, parent):
        # Initialize with empty set and single node
        dp[u][0] = 1
        dp[u][a[u]] = 1

        for v in adj[u]:
            if v == parent:
                continue
            dfs(v, u)

            # Combine dp[u] with dp[v]
            # First, add all sets from dp[v]
            for s, cnt in dp[v].items():
                if s + 0 in dp[u]:
                    dp[u][s + 0] = (dp[u][s + 0] + cnt) % MOD
                else:
                    dp[u][s + 0] = cnt % MOD

            # Then add sets that include u by combining with dp[v] and adding a[u]
            for s, cnt in dp[v].items():
                if s + a[u] in dp[u]:
                    dp[u][s + a[u]] = (dp[u][s + a[u]] + cnt) % MOD
                else:
                    dp[u][s + a[u]] = cnt % MOD

    dfs(0, -1)

    # Count all valid sets with sum >= d
    result = 0
    for s, cnt in dp[0].items():
        if s >= d:
            result = (result + cnt) % MOD

    print(result)

solve()
