def find_cycle(N, edges):
    # Build adjacency list
    adj = [[] for _ in range(N + 1)]
    for a, b in edges:
        adj[a].append(b)

    # Try to find a cycle starting from each vertex
    for start in range(1, N + 1):
        visited = [False] * (N + 1)
        path = []

        def dfs(v):
            if v in path:
                # Found a cycle
                idx = path.index(v)
                cycle = path[idx:]
                return cycle
            if visited[v]:
                return None
            visited[v] = True
            path.append(v)

            for neighbor in adj[v]:
                result = dfs(neighbor)
                if result is not None:
                    return result

            path.pop()
            return None

        cycle = dfs(start)
        if cycle:
            return cycle

    return None

