from collections import deque

def solve():
    V, E, K = map(int, input().split())

    # Build adjacency list
    adj = [[] for _ in range(V)]
    for _ in range(E):
        v1, v2, c = map(int, input().split())
        adj[v1].append((v2, c))

    # max_score[v][e] = maximum score at node v with exactly e edges
    max_score = [[-1] * (101) for _ in range(V)]

    # BFS queue: (node, edges_taken, current_score)
    queue = deque()

    # Initialize: start at each node with 0 edges
    for v in range(V):
        max_score[v][0] = 0
        queue.append((v, 0, 0))

    # BFS
    while queue:
        v, edges, score = queue.popleft()

        # If we've already found a solution with <= 100 edges, we can stop early
        if edges > 100:
            continue

        # Try all outgoing edges
        for next_v, cost in adj[v]:
            new_edges = edges + 1
            new_score = score + cost

            # If we can reach this state with more edges or same edges but higher score
            if new_edges > 100:
                continue
            if max_score[next_v][new_edges] < new_score:
                max_score[next_v][new_edges] = new_score
                queue.append((next_v, new_edges, new_score))

    # Find the minimum number of edges needed to reach score >= K
    min_edges = -1
    for v in range(V):
        for edges in range(101):
            if max_score[v][edges] >= K:
                if min_edges == -1 or edges < min_edges:
                    min_edges = edges

    if min_edges == -1:
        print(-1)
        return

    # Find any path that achieves this
    path = []
    v = -1
    for edges in range(101):
        for node in range(V):
            if max_score[node][edges] >= K:
                v = node
                break
        if v != -1:
            break

    # Reconstruct path
    path.append(v)
    for edges in range(min_edges - 1, -1, -1):
        for node in range(V):
            if max_score[node][edges] >= K:
                path.append(node)
                break

    print(min_edges)
    if min_edges <= 100:
        print(' '.join(map(str, path)))

solve()
"}

