import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        q = int(next(it))
        s = next(it)

        # Precompute b array and prefix sums
        b = []
        prefix = [0] * (n + 1)
        for i in range(1, n + 1):
            if s[i - 1] == '+':
                val = 1
            else:
                val = -1
            if i % 2 == 1:
                b.append(val)
            else:
                b.append(-val)
            prefix[i] = prefix[i - 1] + b[i - 1]

        # Precompute signs
        signs = []
        for i in range(1, n + 1):
            if i % 2 == 1:
                signs.append(1)
            else:
                signs.append(-1)

        # Process queries
        for __ in range(q):
            l = int(next(it))
            r = int(next(it))

            # Compute sum
            total = prefix[r] - prefix[l - 1]

            if total == 0:
                out_lines.append('0')
                out_lines.append('')
            else:
                # Find indices to remove
                if abs(total) == 1:
                    # Need one index with sign = total
                    sign_needed = total
                    found = False
                    for i in range(l - 1, r):
                        if signs[i] == sign_needed:
                            out_lines.append(str(1))
                            out_lines.append(str(i + 1))
                            found = True
                            break
                    if not found:
                        # This shouldn't happen
                        out_lines.append('1')
                        out_lines.append('1')
                else:  # abs(total) == 2
                    # Need two indices with the same sign
                    sign_needed = 1 if total > 0 else -1
                    found1 = False
                    found2 = False
                    for i in range(l - 1, r):
                        if signs[i] == sign_needed:
                            if not found1:
                                out_lines.append(str(1))
                                out_lines.append(str(i + 1))
                                found1 = True
                            elif not found2:
                                out_lines.append(str(2))
                                out_lines.append(str(i + 1))
                                found2 = True
                                break
                    if not found1 or not found2:
                        # This shouldn't happen
                        out_lines.append('2')
                        out_lines.append('1 1')

    sys.stdout.write('\n'.join(out_lines))

if __name__ == '__main__':
    solve()
