def get_pmax(i):
    """Find p_max for number i"""
    if i == 1:
        return 1

    # Prime factorization of i
    prime_factors = {}
    temp = i

    # Check for 2
    count = 0
    while temp % 2 == 0:
        count += 1
        temp //= 2
    if count > 0:
        prime_factors[2] = count

    # Check for odd primes
    for p in range(3, int(temp**0.5) + 1, 2):
        count = 0
        while temp % p == 0:
            count += 1
            temp //= p
        if count > 0:
            prime_factors[p] = count

    if temp > 1:
        prime_factors[temp] = 1

    # Find p_max
    max_exponent = max(prime_factors.values())
    candidates = [p for p, exp in prime_factors.items() if exp == max_exponent]
    return min(candidates)

N, L = map(int, input().split())
A = list(map(int, input().split()))

# Precompute beneficial/harmful for each operation
beneficial = [False] * (L + 1)
for i in range(1, L + 1):
    pmax = get_pmax(i)
    beneficial[i] = (i == 1) or (pmax % i % 2 == 1)

# Process operations
for i in range(1, L + 1):
    if not A:
        break

    if beneficial[i]:
        # Double an element - choose the smallest to avoid overflow
        A[A.index(min(A))] *= 2
    else:
        # Divide an element - choose the largest to minimize loss
        A[A.index(max(A))] //= 2

        # Remove if it becomes 0
        if A[A.index(max(A))] == 0:
            A.remove(0)

# Output
print(len(A))
print(' '.join(map(str, sorted(A))))
"}

