def solve():
    n, m = map(int, input().split())
    segments = []
    for _ in range(n):
        l, r, w = map(int, input().split())
        segments.append((l, r, w))

    # Binary search on the answer
    left = 0
    right = 10**6  # Maximum possible value

    def is_possible(range_low, range_high):
        # Create DSU for points 1..m
        parent = list(range(m + 1))

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            parent[find(x)] = find(y)

        # Process all segments in the range
        for l, r, w in segments:
            if range_low <= w <= range_high:
                # Connect all points in [l, r]
                for i in range(l, r + 1):
                    if i + 1 <= r:
                        union(i, i + 1)

        return find(1) == find(m)

    answer = 0
    while left <= right:
        mid = (left + right) // 2
        if is_possible(0, mid):
            answer = mid
            right = mid - 1
        else:
            left = mid + 1

    print(answer)

solve()
