def count_distinct(arr, l, r):
    """Count distinct elements in subarray arr[l:r+1]"""
    return len(set(arr[l:r+1]))

def is_minimal_by_inclusion(arr, l, r, k):
    """Check if segment [l, r] is minimal by inclusion"""
    # Check if removing leftmost element reduces distinct count
    if count_distinct(arr, l+1, r) < k:
        return True
    # Check if removing rightmost element reduces distinct count
    if count_distinct(arr, l, r-1) < k:
        return True
    return False

