K, S = map(int, input().split())

# Number of non-negative integer solutions to X + Y + Z = S
# without constraints: C(S + 2, 2) = (S+2)*(S+1)//2
# But we have constraints 0 <= X, Y, Z <= K

if S > 3 * K:
    ans = 0
elif S > 2 * K:
    ans = (S - 2 * K - 1) * (S - 2 * K) // 2
elif S > K:
    ans = 3 * (S - K - 1) * (S - K) // 2 - 3 * (S - 2 * K - 1) * (S - 2 * K) // 2
else:
    ans = (S + 2) * (S + 1) // 2

print(ans)
"}

